// ======= FAVORITES SYSTEM =======
class FavoritesManager {
  constructor() {
    this.favorites = JSON.parse(localStorage.getItem("jawwad-favorites") || "[]")
    this.userFingerprint = this.generateFingerprint()
  }

  generateFingerprint() {
    // Simple fingerprint based on screen, timezone, language
    const canvas = document.createElement("canvas")
    const ctx = canvas.getContext("2d")
    ctx.textBaseline = "top"
    ctx.font = "14px Arial"
    ctx.fillText("Jawwad ART", 2, 2)

    return btoa(
      screen.width +
        screen.height +
        navigator.language +
        Intl.DateTimeFormat().resolvedOptions().timeZone +
        canvas.toDataURL(),
    ).slice(0, 16)
  }

  isFavorite(itemId) {
    return this.favorites.some((fav) => fav.id === itemId)
  }

  toggle(itemId, itemData) {
    if (this.isFavorite(itemId)) {
      this.remove(itemId)
    } else {
      this.add(itemId, itemData)
    }
    this.save()
    this.updateUI()
  }

  add(itemId, itemData) {
    if (!this.isFavorite(itemId)) {
      this.favorites.push({
        id: itemId,
        data: itemData,
        timestamp: new Date().toISOString(),
      })
      showToast("Added to favorites! ❤️")

      // Save to cloud (GitHub) - simplified version
      this.saveToCloud(itemId, itemData, "add")
    }
  }

  remove(itemId) {
    this.favorites = this.favorites.filter((fav) => fav.id !== itemId)
    showToast("Removed from favorites! 💔")

    // Remove from cloud
    this.saveToCloud(itemId, null, "remove")
  }

  save() {
    localStorage.setItem("jawwad-favorites", JSON.stringify(this.favorites))
  }

  async saveToCloud(itemId, itemData, action) {
    try {
      // This would normally send to a backend API
      // For now, we'll just log it (you can implement GitHub API later)
      console.log("Cloud save:", {
        fingerprint: this.userFingerprint,
        itemId,
        itemData,
        action,
        timestamp: new Date().toISOString(),
      })
    } catch (error) {
      console.error("Failed to save to cloud:", error)
    }
  }

  updateUI() {
    // Update all favorite buttons
    document.querySelectorAll(".favorite-btn").forEach((btn) => {
      const itemId = btn.dataset.itemId
      const icon = btn.querySelector("i")
      if (this.isFavorite(itemId)) {
        icon.className = "fas fa-heart"
        btn.classList.add("favorited")
      } else {
        icon.className = "far fa-heart"
        btn.classList.remove("favorited")
      }
    })

    // Update favorites count
    const favCount = document.getElementById("favorites-count")
    if (favCount) {
      favCount.textContent = this.favorites.length
    }
  }

  getFavorites() {
    return this.favorites
  }

  showFavoritesList() {
    if (this.favorites.length === 0) {
      showToast("No favorites yet! ❤️ Add some assets to your favorites.")
      return
    }

    const modal = document.getElementById("favorites-modal")
    const favoritesList = document.getElementById("favorites-list")

    if (!modal || !favoritesList) return

    // Generate favorites list HTML
    const favoritesHTML = this.favorites
      .map((fav) => {
        const item = fav.data || {} // Ensure data exists
        return `
      <div class="favorite-item">
        <div class="favorite-item-image">
          ${item.img ? `<img src="${item.img}" alt="${item.title || "Asset"}" loading="lazy">` : '<div class="no-image"><i class="fas fa-image"></i></div>'}
        </div>
        <div class="favorite-item-content">
          <h4>${item.title || "Unknown Asset"}</h4>
          <p class="favorite-item-category">${fav.id.split("-")[0]}</p>
          ${item.desc ? `<p class="favorite-item-desc">${item.desc.slice(0, 80)}${item.desc.length > 80 ? "..." : ""}</p>` : ""}
          ${item.price ? `<span class="favorite-item-price">${item.price}</span>` : ""}
        </div>
        <button class="favorite-remove-btn" onclick="favoritesManager.remove('${fav.id}'); favoritesManager.showFavoritesList()" title="Remove from favorites">
          <i class="fas fa-trash"></i>
        </button>
      </div>
    `
      })
      .join("")

    favoritesList.innerHTML = `
      <div class="favorites-header">
        <h3>Your Favorites (${this.favorites.length})</h3>
        <button onclick="closeFavoritesModal()" class="favorites-close">
          <i class="fas fa-times"></i>
        </button>
      </div>
      <div class="favorites-content">
        ${favoritesHTML}
      </div>
    `

    modal.classList.remove("hidden")
    document.body.style.overflow = "hidden"
  }
}

// ======= SEARCH SYSTEM =======
class SearchManager {
  constructor() {
    this.allAssets = []
    this.searchIndex = new Map()
    this.isSearching = false
    this.searchTimeout = null
  }

  async loadAllAssets() {
    const categories = ["costumes", "hairstyles", "weapons", "others", "free", "tools"]
    this.allAssets = []

    for (const category of categories) {
      try {
        const response = await fetch(`assets/data/${category}.json?v=${Date.now()}`)
        if (response.ok) {
          const data = await response.json()
          data.forEach((item) => {
            this.allAssets.push({
              ...item,
              category,
              id: `${category}-${item.title.toLowerCase().replace(/\s+/g, "-")}`,
            })
          })
        }
      } catch (error) {
        console.error(`Failed to load ${category}:`, error)
      }
    }

    this.buildSearchIndex()
  }

  buildSearchIndex() {
    this.searchIndex.clear()
    this.allAssets.forEach((asset) => {
      const searchText = `${asset.title} ${asset.desc || ""} ${asset.category}`.toLowerCase()
      const words = searchText.split(/\s+/)

      words.forEach((word) => {
        if (word.length > 2) {
          if (!this.searchIndex.has(word)) {
            this.searchIndex.set(word, [])
          }
          this.searchIndex.get(word).push(asset)
        }
      })
    })
  }

  search(query) {
    if (!query || query.length < 2) return []

    const words = query.toLowerCase().split(/\s+/)
    const results = new Map()

    words.forEach((word) => {
      this.searchIndex.forEach((assets, indexWord) => {
        if (indexWord.includes(word)) {
          assets.forEach((asset) => {
            const score = (results.get(asset.id) || 0) + 1
            results.set(asset.id, score)
          })
        }
      })
    })

    // Sort by relevance score
    return Array.from(results.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([assetId]) => this.allAssets.find((asset) => asset.id === assetId))
      .filter(Boolean)
  }

  setupSearchUI() {
    const searchInput = document.getElementById("search-input")
    const searchResults = document.getElementById("search-results")
    const searchOverlay = document.getElementById("search-overlay")

    if (!searchInput) return

    searchInput.addEventListener("input", (e) => {
      clearTimeout(this.searchTimeout)
      this.searchTimeout = setTimeout(() => {
        this.handleSearch(e.target.value)
      }, 150)
    })

    searchInput.addEventListener("focus", () => {
      searchOverlay?.classList.add("active")
    })

    // Close search on overlay click
    searchOverlay?.addEventListener("click", (e) => {
      if (e.target === searchOverlay) {
        this.closeSearch()
      }
    })

    // Close search on escape
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        this.closeSearch()
      }
    })
  }

  handleSearch(query) {
    const searchResults = document.getElementById("search-results")
    if (!searchResults) return

    if (!query || query.length < 1) {
      searchResults.innerHTML = `
        <div class="search-placeholder">
          <i class="fas fa-search"></i>
          <p>Start typing to search assets...</p>
        </div>
      `
      return
    }

    this.isSearching = true
    searchResults.innerHTML = `
      <div class="search-loading">
        <div class="loading-spinner"></div>
        <p>Searching...</p>
      </div>
    `

    setTimeout(() => {
      const results = this.search(query)
      this.displayResults(results, query)
      this.isSearching = false
    }, 100)
  }

  displayResults(results, query) {
    const searchResults = document.getElementById("search-results")
    if (!searchResults) return

    if (results.length === 0) {
      searchResults.innerHTML = `
        <div class="search-no-results">
          <i class="fas fa-search-minus"></i>
          <p>No results found for "${query}"</p>
          <small>Try different keywords or check spelling</small>
        </div>
      `
      return
    }

    const resultsHTML = results
      .map(
        (asset) => `
      <div class="search-result-item" onclick="openAssetFromSearch('${asset.category}', '${asset.id}')">
        <div class="search-result-image">
          ${asset.img ? `<img src="${asset.img}" alt="${asset.title}" loading="lazy">` : '<div class="no-image"><i class="fas fa-image"></i></div>'}
        </div>
        <div class="search-result-content">
          <h4>${this.highlightQuery(asset.title, query)}</h4>
          <p class="search-result-category">${asset.category}</p>
          ${asset.desc ? `<p class="search-result-desc">${this.highlightQuery(asset.desc.slice(0, 100), query)}${asset.desc.length > 100 ? "..." : ""}</p>` : ""}
          ${asset.price ? `<span class="search-result-price">${asset.price}</span>` : ""}
        </div>
        <button class="favorite-btn search-favorite" data-item-id="${asset.id}" onclick="event.stopPropagation(); favoritesManager.toggle('${asset.id}', ${JSON.stringify(asset).replace(/"/g, "&quot;")})">
          <i class="${favoritesManager.isFavorite(asset.id) ? "fas" : "far"} fa-heart"></i>
        </button>
      </div>
    `,
      )
      .join("")

    searchResults.innerHTML = `
      <div class="search-results-header">
        <h3>Found ${results.length} result${results.length !== 1 ? "s" : ""}</h3>
      </div>
      <div class="search-results-list">
        ${resultsHTML}
      </div>
    `
  }

  highlightQuery(text, query) {
    if (!query) return text
    const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")})`, "gi")
    return text.replace(regex, "<mark>$1</mark>")
  }

  closeSearch() {
    const searchOverlay = document.getElementById("search-overlay")
    const searchInput = document.getElementById("search-input")

    searchOverlay?.classList.remove("active")
    if (searchInput) {
      searchInput.blur()
    }
  }
}

