// ======= INITIALIZATION =======
function initializeApp() {
  DOM.init()

  // Initialize managers
  favoritesManager = new FavoritesManager()
  searchManager = new SearchManager()

  // Load all assets for search
  searchManager.loadAllAssets()
  searchManager.setupSearchUI()

  // Set up event listeners with better performance
  const mobileMenuButton = document.getElementById("mobile-menu-button")
  if (mobileMenuButton) {
    mobileMenuButton.addEventListener("click", () => {
      const mobileMenu = document.getElementById("mobile-menu")
      mobileMenu?.classList.toggle("hidden")
    })
  }

  const imageModal = document.getElementById("image-modal")
  if (imageModal) {
    imageModal.addEventListener("click", (e) => {
      if (e.target === e.currentTarget) closeModal()
    })
  }

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      closeModal()
      closeFavoritesModal()
    }
  })

  // Optimize dropdown links
  document.querySelectorAll(".dropdown-content a").forEach((link) => {
    link.addEventListener("click", toggleDropdown)
  })

  // Optimized intersection observer
  const observerOptions = {
    threshold: 0.1,
    rootMargin: "50px",
  }

  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add("opacity-100", "translate-y-0")
        observer.unobserve(entry.target)
      }
    })
  }, observerOptions)

  // Observe fade images
  document.querySelectorAll(".fade-img").forEach((img) => {
    observer.observe(img)
  })

  // Load initial page
  const savedPage = localStorage.getItem("currentPage")
  if (savedPage === "assets") {
    loadAllAssets()
  } else if (savedPage) {
    loadContent(savedPage)
  } else {
    renderWelcomeContent()
  }
}

// Initialize when DOM is ready
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", initializeApp)
} else {
  initializeApp()
}

// Mobile menu handler
document.addEventListener("DOMContentLoaded", () => {
  const menuBtn = document.querySelector(".menu-btn")
  const navbarMenu = document.querySelector(".navbar-menu")

  if (menuBtn && navbarMenu) {
    menuBtn.addEventListener("click", () => {
      navbarMenu.classList.toggle("active")
      menuBtn.classList.toggle("active")
    })
  }
})

// Intersection observer for fade images
const observer = new IntersectionObserver(
  (entries) => {
    entries.forEach((entry) => {
      if (entry.isIntersecting) {
        entry.target.classList.add("opacity-100", "translate-y-0")
        observer.unobserve(entry.target)
      }
    })
  },
  { threshold: 0.1 },
)

document.querySelectorAll(".fade-img").forEach((img) => {
  observer.observe(img)
})
